    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def getf(obj, key, default=None):
        try:
            return obj.get(key, default)
        except Exception:
            return default

    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def sign_toward(a, b):
        return [clamp_step(b[0] - a[0]), clamp_step(b[1] - a[1])]

    def safe_points(v):
        out = []
        if isinstance(v, (list, tuple)):
            for item in v:
                if isinstance(item, (list, tuple)) and len(item) >= 2:
                    out.append((item[0], item[1]))
        return out

    env = getf(observation, "environment_name", "") or ""
    role = getf(observation, "self_role", "") or ""
    sx, sy = pos(getf(observation, "self_position"))
    ox, oy = pos(getf(observation, "opponent_position"), (sx, sy))
